    home_card_contract_desc: "Pega cualquier dirección de token para ver al instante si es segura, sospechosa o una estafa conocida.",
    home_card_contract_title: "Comprobador de contratos",
    home_card_scams_desc: "Conoce las tácticas más comunes que usan los estafadores para robar a los holders de cripto.",
    home_card_scams_title: "Estafas comunes",
    home_card_tips_desc: "Comisiones de gas, slippage, conexiones de billetera y firma de transacciones — explicado de forma simple.",
    home_card_tips_title: "Consejos y ayuda",
    home_card_url_desc: "Verifica una URL antes de conectar tu billetera — un sitio equivocado puede vaciarla en segundos.",
    home_card_url_title: "Comprobador de sitios web",
    home_card_wallet_desc: "Confirma que una dirección de destino es válida antes de enviar cripto que no podrás recuperar.",
    home_card_wallet_title: "Verificador de billetera",
    home_intro: "OrcaGuard reúne ocho herramientas de seguridad en un solo lugar. Desde comprobar contratos desconocidos y URLs de phishing, hasta auditar tu billetera y aprender cómo funcionan las estafas — todo explicado en lenguaje sencillo, sin conocimientos técnicos.",
    home_start_html: "<div style=\"display:grid;gap:6px\"><div style=\"font-size:18px;color:var(--text);line-height:1.5\">📋 <strong style=\"color:#fff\">¿Tienes una dirección simbólica?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('contract')\">Comprobador de contratos</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌐 <strong style=\"color:#fff\">¿No estás seguro acerca de un sitio web?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('url')\">Comprobador de sitios web</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🔐 <strong style=\"color:#fff\">¿Quieres ver qué hay en tu billetera?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('audit')\">Auditoría de billetera</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌱 <strong style=\"color:#fff\">¿Nuevo en las criptomonedas?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('scams')\">Estafas comunes</span></div></div>",
