    home_card_url_title: "Verificador de sites",
    home_card_wallet_desc: "Confirme se um endereço de destino é válido antes de enviar criptografia que você nunca poderá recuperar.",
    home_card_wallet_title: "Verificador de carteira",
    home_intro: "OrcaGuard reúne oito ferramentas de segurança em um só lugar. Desde verificar contratos desconhecidos e URLs de phishing até auditar sua própria carteira e aprender como funcionam os golpes – tudo é explicado em inglês simples, sem necessidade de conhecimento técnico.",
    home_start_html: "<div style=\"display:grid;gap:6px\"><div style=\"font-size:18px;color:var(--text);line-height:1.5\">📋 <strong style=\"color:#fff\">Tem um endereço de token?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('contract')\">Verificador de contrato</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌐 <strong style=\"color:#fff\">Não tem certeza sobre um site?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('url')\">Verificador de sites</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🔐 <strong style=\"color:#fff\">Quer ver o que tem em sua carteira?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('audit')\">Auditoria de carteira</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌱 <strong style=\"color:#fff\">Novo em criptografia?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('scams')\">Golpes Comuns</span></div></div>",
