    home_card_wallet_desc: "Bestätigen Sie, dass eine Zieladresse gültig ist, bevor Sie Kryptowährungen senden, die Sie nie zurückerhalten können.",
    home_card_wallet_title: "Wallet-Verifizierer",
    home_intro: "OrcaGuard vereint acht Sicherheitstools an einem Ort. Von der Überprüfung unbekannter Verträge und Phishing-URLs über die Prüfung Ihres eigenen Wallets bis hin zum Erlernen der Funktionsweise von Betrügereien – alles wird in einfachem Englisch erklärt, es sind keine technischen Vorkenntnisse erforderlich.",
    home_start_html: "<div style=\"display:grid;gap:6px\"><div style=\"font-size:18px;color:var(--text);line-height:1.5\">📋 <strong style=\"color:#fff\">Haben Sie eine Token-Adresse?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('contract')\">Vertragsprüfung</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌐 <strong style=\"color:#fff\">Sie sind sich bei einer Website nicht sicher?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('url')\">Website Checker</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🔐 <strong style=\"color:#fff\">Möchten Sie sehen, was sich in Ihrer Brieftasche befindet?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('audit')\">Wallet Audit</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌱 <strong style=\"color:#fff\">Neu bei Krypto?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('scams')\">Häufige Betrügereien</span></div></div>",
