    home_card_wallet_title: "钱包验证器",
    home_intro: "OrcaGuard 将八项安全工具集于一处。从检查未知合约和钓鱼网址，到审计您的钱包、了解骗局套路 — 一切均以通俗易懂的语言说明，无需技术背景。",
    home_start_html: "<div style=\"display:grid;gap:6px\"><div style=\"font-size:18px;color:var(--text);line-height:1.5\">📋 <strong style=\"color:#fff\">有代币地址？</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('contract')\">合约检查器</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌐 <strong style=\"color:#fff\">不确定某个网站？</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('url')\">网站检查器</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🔐 <strong style=\"color:#fff\">想看看钱包里有什么？</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('audit')\">钱包审计</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌱 <strong style=\"color:#fff\">刚接触加密货币？</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('scams')\">常见骗局</span></div></div>",
